/* C API of the Rust port of `solveroot.c`, generated by rust-anything. */
#ifndef SOLVEROOT_RS_H
#define SOLVEROOT_RS_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <sys/types.h>

double SolveRootX(int algo, int numOfIter, double Eps, int MaxIte, int func, double a, double b, double c, double X_0, double X_1);
int SolveRootFlag(int algo, int numOfIter, double Eps, int MaxIte, int func, double a, double b, double c, double X_0, double X_1);
int SolveRoot2Algo(int start, int calls, double Eps, int maxIters, int func, double a, double b, double c, double X_0, double X_1);
double SolveRoot2X(int start, int calls, double Eps, int maxIters, int func, double a, double b, double c, double X_0, double X_1);

/* The same functions under `rust_anything_` names, for shadow runs. */
double rust_anything_SolveRootX(int algo, int numOfIter, double Eps, int MaxIte, int func, double a, double b, double c, double X_0, double X_1);
int rust_anything_SolveRootFlag(int algo, int numOfIter, double Eps, int MaxIte, int func, double a, double b, double c, double X_0, double X_1);
int rust_anything_SolveRoot2Algo(int start, int calls, double Eps, int maxIters, int func, double a, double b, double c, double X_0, double X_1);
double rust_anything_SolveRoot2X(int start, int calls, double Eps, int maxIters, int func, double a, double b, double c, double X_0, double X_1);

#endif /* SOLVEROOT_RS_H */
